files.child.sh:
expected=$1
mode=$2
case $mode in
  caught) trap 'printf "caught=%s\n" "$expected" >&4; exit 23' "$expected" ;;
  default) trap - "$expected" ;;
  ignored) : ;;
  *) exit 97 ;;
esac
printf 'ready %s\n' "$BASHPID" >&4
if [[ $mode == ignored ]]; then
  disposition=$(trap -p "$expected")
  if [[ $disposition == *"''"* ]]; then printf 'ignored-inherited=yes\n' >&4
  else printf 'ignored-inherited=no\n' >&4; fi
fi
while IFS= read -r request <&3; do
  case $request in
    ping) printf 'pong\n' >&4 ;;
    quit) exit 0 ;;
    *) exit 98 ;;
  esac
done
exit 99

